package main
import("bytes";"encoding/json";"fmt";"os";"os/exec";"runtime";"strings")
func require(v bool,label string){if !v{fmt.Fprintln(os.Stderr,"FAIL",label);os.Exit(1)}}
func call(expected int,input string,args ...string)map[string]any{cmd:=exec.Command("/tmp/memoryaffe",append([]string{"--json","--allow-local-http"},args...)...);cmd.Stdin=strings.NewReader(input);var out,err bytes.Buffer;cmd.Stdout=&out;cmd.Stderr=&err;e:=cmd.Run();code:=0;if e!=nil{if x,ok:=e.(*exec.ExitError);ok{code=x.ExitCode()}else{require(false,"could not execute native Linux CLI")}};require(code==expected,"native Linux CLI exit for "+strings.Join(args[:min(2,len(args))]," ")+fmt.Sprint(" = ",code));token:=os.Getenv("MEMORYAFFE_TOKEN");require(!strings.Contains(out.String()+err.String(),token),"native CLI token leak");var data map[string]any;require(json.Unmarshal(out.Bytes(),&data)==nil,"native CLI stdout not JSON");return data}
func main(){require(runtime.GOOS=="linux","smoke must execute natively on Linux");vault:=os.Getenv("MEMORYAFFE_TEST_VAULT");require(vault!="","test vault missing");call(0,"","doctor");v:=call(0,"","vault","list","--page-size","100");require(len(v["items"].([]any))==1,"Linux vault isolation");tag:=call(0,"","tag","create","--vault",vault,"--name","Linux native tag");tags:=call(0,"","tag","list","--vault",vault);require(len(tags["items"].([]any))==1,"Linux tag list");text:="# Grüße α😀\r\n\r\nLinux native\r\n";require(os.WriteFile("/tmp/native.md",[]byte(text),0600)==nil,"file fixture");created:=call(0,"","memory","create","--vault",vault,"--title","LinuxNativeMemory","--file","/tmp/native.md","--tag",tag["id"].(string));id:=created["id"].(string);got:=call(0,"","memory","get",id);require(got["markdown"]==text,"Linux UTF8/CRLF file preservation");updated:=call(0,"","memory","update",id,"--revision",created["revision"].(string),"--stdin","--clear-summary","--clear-tags");empty:=call(0,"","memory","get",id);require(empty["markdown"]==""&&empty["summary"]==nil&&len(empty["tags"].([]any))==0,"Linux empty stdin and clear fields");search:=call(0,"","memory","search","--vault",vault,"--query","LinuxNativeMemory");require(len(search["items"].([]any))==1,"Linux search");call(0,"","memory","delete",id,"--revision",updated["revision"].(string));call(5,"","memory","get",id);fmt.Printf("PASS native Linux %s/%s all eight CLI operations, doctor, Unicode/CRLF, empty stdin and delete exit\n",runtime.GOOS,runtime.GOARCH)}
